#!/usr/bin/env bash
# Q1 upgrade bundle 1: paired-CV calibration (NTC-full fix) + joint router+budget.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Q1 upgrade bundle 1..."
decode "scripts/ntc_w1_stats.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_figures.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_joint_router.py" << 'B64EOF'

B64EOF
pip show scikit-learn >/dev/null 2>&1 || pip install scikit-learn -q
echo ""
echo "Installed. Run (all instant, no GPU):"
echo "  # 1) re-run stats with paired-CV calibration (all 4 benchmarks)"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_math500_Qwen3-4B.json"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_gsm8k_Qwen3-4B.json"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_gpqa16k_Qwen3-4B.json"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_math500_Qwen3-1.7B.json"
echo "  # 2) regenerate RESULTS.md + figures"
echo "  python scripts/ntc_w1_figures.py --probes experiments/ntc/w1_math500_Qwen3-4B.json --probes experiments/ntc/w1_gsm8k_Qwen3-4B.json --probes experiments/ntc/w1_gpqa16k_Qwen3-4B.json --probes experiments/ntc/w1_math500_Qwen3-1.7B.json"
echo "  # 3) JOINT router+budget (the unification result)"
echo "  python scripts/ntc_joint_router.py --small experiments/ntc/w1_math500_Qwen3-1.7B.json --large experiments/ntc/w1_math500_Qwen3-4B.json"